function snapshot(){return {layers:Object.fromEntries(Object.entries(layers).map(([id,l])=>[id,{...l}])),mode,media,images,selectedLayer,titleLanguage,sourceState:snapshotSources(),seasonState:snapshotSeasons(),name:$('workspaceName').textContent,search:$('search').value}}
