function updateUndo(){$('undoBtn').disabled=!undoStack.length}
function restore(state){restoreSources(state.sourceState);restoreSeasons(state.seasonState);selectionVersion++;searchVersion++;brandVersion++;randomVersion++;artworkVersions.poster++;artworkVersions.title++;for(const [id,l] of Object.entries(state.layers))Object.assign(layers[id],l);mode=state.mode;media=state.media;images=state.images;selectedLayer=state.selectedLayer;titleLanguage=state.titleLanguage||"all";$('workspaceName').textContent=state.name;$('search').value=state.search;$('tvTab').classList.toggle('active',mode==='tv');$('movieTab').classList.toggle('active',mode==='movie');$('search').placeholder=mode==='tv'?'Search TV shows…':'Search movies…';$('results').innerHTML='';$('demoBtn').disabled=false;editTarget=null;refresh();properties();updateUndo()}
function undo(){if(!undoStack.length)return;redoStack.push(snapshot());restore(undoStack.pop());status('Last edit undone.')}
function redo(){if(!redoStack.length)return;undoStack.push(snapshot());restore(redoStack.pop());status('Edit restored.')}

