let brandVersion=0;
async function selectBrand(id,record=true){const before=snapshot();const version=++brandVersion,b=brands.find(b=>b.id===id);if(!b){if(record)checkpoint(before);Object.assign(layers.service,{img:null,brandId:''});refresh();properties();return}try{let raw=b.svg;if(!raw){const response=await fetch(b.src);if(!response.ok)throw new Error('This bundled logo could not be loaded. Upload an SVG in the logo library.');raw=await response.text()}const img=await trimLogo(await loadImage(svgURL(sanitizeSvg(raw))));if(version!==brandVersion)return;if(record)checkpoint(before);Object.assign(layers.service,{img,brandId:id,visible:true,recolor:true,color:'#ffffff'});const preset=servicePreset();layers.service.recolor=!preset.original;layers.service.color=preset.color||'#ffffff';serviceLayout();refresh();properties()}catch(e){status(e.message)}}
async function api(path,params={},signal){if(!credential)throw new Error('Connect TMDB first, or upload your own artwork.');const u=new URL('https://api.themoviedb.org/3/'+path);Object.entries(params).forEach(([k,v])=>u.searchParams.set(k,v));const headers={accept:'application/json'};if(credential.length<60)u.searchParams.set('api_key',credential);else headers.Authorization='Bearer '+credential;const r=await fetch(u,{headers,signal});if(!r.ok)throw new Error(r.status===401?'TMDB rejected this credential. Check your token or API key.':r.status===429?'TMDB is busy. Please try again shortly.':`TMDB request failed (${r.status}).`);return r.json()}
async function searchTitles(){const q=$('search').value.trim(),version=++searchVersion;if(q.length<2){$('results').innerHTML='';return}if(!credential){$('results').innerHTML='<p class="muted">Connect TMDB using the button above to search.</p>';return}$('results').innerHTML='<p class="muted">Searching…</p>';try{const data=await api(`search/${mode}`,{query:q,include_adult:false,language:'en-US'});if(version!==searchVersion)return;$('results').innerHTML=data.results.slice(0,8).map(t=>`<button class="result" data-result="${t.id}">${t.poster_path?`<img src="${imageURL(t.poster_path,'w92')}" alt="">`:'<span>▧</span>'}<span>${esc(t.name||t.title)}<small>${esc((t.first_air_date||t.release_date||'').slice(0,4)||'Unknown year')}</small></span></button>`).join('')||'<p class="muted">No matching titles. Try another name.</p>';const map=new Map(data.results.map(t=>[t.id,t]));$('results').querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>selectTitle(map.get(Number(b.dataset.result))))}catch(e){if(version===searchVersion)$('results').textContent=e.message}}
function filteredTitleLogos(){return images.logos.filter(p=>titleLanguage==='all'||(p.iso_639_1||'neutral')===titleLanguage)}
function renderTitleLanguages(){const codes=[...new Set(images.logos.map(p=>p.iso_639_1||'neutral'))].sort();const names=new Intl.DisplayNames(['en'],{type:'language'});$('titleLanguage').innerHTML='<option value="all">All languages</option>'+codes.map(code=>`<option value="${esc(code)}">${esc(code==='neutral'?'Language-neutral':names.of(code)||code)}</option>`).join('');$('titleLanguage').value=titleLanguage;$('titleLanguageField').hidden=selectedLayer!=='title'}
function renderArtwork(){renderTitleLanguages();const active=['poster','title'].includes(selectedLayer);$('artworkPanel').hidden=!active;if(!active)return;assetTab=selectedLayer==='poster'?'posters':'logos';$('artworkLabel').textContent=selectedLayer==='poster'?'Poster artwork':'Title artwork';$('uploadPosterBtn').hidden=selectedLayer!=='poster';$('uploadTitleBtn').hidden=selectedLayer!=='title';$('artworkSource').value=artworkSource;let list=assetTab==='posters'?images.posters.filter(p=>($('includeUnknownLanguage').checked||p.iso_639_1!=='und')&&(!$('neutralOnly').checked||p.iso_639_1===null||p.iso_639_1==='und')):filteredTitleLogos();list=list.filter(p=>(artworkSource==='all'||(p.source||'tmdb')===artworkSource)&&assetURL(p));$('assetCount').textContent=list.length;$('neutralOnly').closest('label').hidden=assetTab!=='posters';$('includeUnknownLanguage').closest('label').hidden=assetTab!=='posters';$('artwork').innerHTML=list.length?list.map((p,i)=>`<button data-art="${i}" title="${esc(assetLabel(p))}" class="${layers[selectedLayer].src===assetURL(p)?'selected':''}"><img crossorigin="anonymous" class="${assetTab==='logos'?'logo-thumb':''}" src="${esc(assetURL(p,assetTab==='posters'?'w185':'w500'))}" alt="${AssetSources.names[p.source||'tmdb']} ${assetTab==='posters'?'poster':'title logo'} option ${i+1}" loading="lazy"><span class="asset-source">${AssetSources.names[p.source||'tmdb']}</span></button>`).join(''):`<p class="muted">${media?'No matching artwork. Try another source or language filter, or upload your own.':'Select a TMDB title or upload artwork.'}</p>`;const layer=selectedLayer;$('artwork').querySelectorAll('[data-art]').forEach(b=>b.onclick=()=>setArtwork(layer,assetURL(list[Number(b.dataset.art)])))}

const artworkVersions={poster:0,title:0};
async function setArtwork(layer,src,record=true){const before=snapshot();const v=++artworkVersions[layer];try{status('Loading artwork…');const img=await loadImage(src);if(v!==artworkVersions[layer])return false;if(record)checkpoint(before);Object.assign(layers[layer],{img,src,visible:true});refresh();renderArtwork();status('Artwork ready. Make it yours.');return true}catch(e){if(v===artworkVersions[layer])status(e.message);return false}}
async function selectTitle(t,fromRandom=false){if(!fromRandom){randomVersion++;$('demoBtn').disabled=false}checkpoint();clearTimeout(searchTimer);searchVersion++;clearSources();clearSeasons();const version=++selectionVersion;artworkVersions.poster++;artworkVersions.title++;brandVersion++;const currentMode=mode;media=t;selectedLayer='poster';layers.poster.visible=true;layers.gradient.visible=true;layers.title.visible=true;layers.service.visible=true;images={posters:[],logos:[]};Object.assign(layers.poster,{img:null,src:''});Object.assign(layers.title,{img:null,src:''});Object.assign(layers.service,{img:null,brandId:'',shadowEnabled:false});layout();$('results').innerHTML='';$('search').value=t.name||t.title;$('workspaceName').textContent=t.name||t.title;renderArtwork();status('Finding posters, title logos, and networks…');try{const [detail,art]=await Promise.all([api(`${currentMode}/${t.id}`),api(`${currentMode}/${t.id}/images`)]);if(version!==selectionVersion)return;if(currentMode==='tv')seasonDefinitions=(detail.seasons||[]).filter(s=>Number.isInteger(s.season_number)&&s.season_number>=0);images={posters:art.posters||[],logos:(art.logos||[]).sort((a,b)=>(b.iso_639_1==='en')-(a.iso_639_1==='en')||(b.vote_average||0)-(a.vote_average||0))};titleLanguage=images.logos.some(p=>p.iso_639_1==='en')?'en':'all';const poster=images.posters.find(p=>p.iso_639_1===null);const jobs=[];if(poster)jobs.push(setArtwork('poster',imageURL(poster.file_path),false));else if(t.poster_path)jobs.push(setArtwork('poster',imageURL(t.poster_path),false));if(images.logos[0])jobs.push(setArtwork('title',imageURL(images.logos[0].file_path),false));const names=(currentMode==='tv'?detail.networks:detail.production_companies)||[];let brand=names.map(n=>matchBrand(n.name,names)).find(Boolean);if(!brand){try{const providers=await api(`${currentMode}/${t.id}/watch/providers`);if(version!==selectionVersion)return;brand=(providers.results?.[region]?.flatrate||[]).map(n=>matchBrand(n.provider_name)).find(Boolean)}catch{}}jobs.push(selectBrand(brand?.id||'',false));await Promise.all(jobs);if(version!==selectionVersion)return;if(seasonMode&&currentMode==='tv')await loadSeasons();if(version!==selectionVersion)return;renderArtwork();status((!layers.poster.img?'No usable poster loaded; upload your own artwork.':poster?'Language-neutral poster selected.':'No language-neutral poster found; using the standard poster.')+(brand?` ${brand.name} suggested from TMDB metadata / ${region} streaming availability.`:' Choose a service or studio logo manually.')+(!images.logos.length?' No title logo found; you can upload one.':''));void loadExternalArtwork()}catch(e){if(version===selectionVersion)status(e.message)}}
function setMode(next){if(mode===next)return;checkpoint();clearSources();clearSeasons();mode=next;if(next==='movie')seasonMode=false;randomVersion++;$('demoBtn').disabled=false;selectedLayer='poster';selectionVersion++;searchVersion++;$('tvTab').classList.toggle('active',mode==='tv');$('movieTab').classList.toggle('active',mode==='movie');$('search').placeholder=mode==='tv'?'Search TV shows…':'Search movies…';$('search').value='';$('results').innerHTML='';media=null;layers.gradient.visible=true;layers.title.visible=true;layers.service.visible=true;images={posters:[],logos:[]};artworkVersions.poster++;artworkVersions.title++;brandVersion++;for(const id of ['poster','title','service']){layers[id].img=null;layers[id].src=''}layers.service.brandId='';layers.service.shadowEnabled=false;$('workspaceName').textContent='Untitled poster';layout();renderArtwork();status('Ready when you are.')}
