// Custom color editor: HSV square, hue strip, hex input and poster sampling.
let colorEditor=null;
function hexToHSV(hex){const [r,g,b]=hex.match(/\w\w/g).map(v=>parseInt(v,16)/255),max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;let h=0;if(d)h=max===r?((g-b)/d)%6:max===g?(b-r)/d+2:(r-g)/d+4;return {h:(h*60+360)%360,s:max?d/max:0,v:max}}
function hsvToHex(h,s,v){const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c;const rgb=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return '#'+rgb.map(n=>Math.round((n+m)*255).toString(16).padStart(2,'0')).join('')}
function openColorPicker(layer,key){cancelColorPick();colorEditor={layer,key,...hexToHSV(colorLayer(layer)[key]),recorded:false};paintColorPicker();$('colorPicker').showModal()}
function paintColorPicker(){if(!colorEditor)return;const {h,s,v,layer,key}=colorEditor;$('colorSquare').style.backgroundColor=hsvToHex(h,1,1);$('colorHandle').style.left=s*100+'%';$('colorHandle').style.top=(1-v)*100+'%';$('colorSquare').setAttribute('aria-valuenow',Math.round(s*100));$('colorSquare').setAttribute('aria-valuetext',`Saturation ${Math.round(s*100)}%, brightness ${Math.round(v*100)}%`);$('colorHue').value=h;$('pickerHex').value=colorLayer(layer)[key];$('pickerHex').setAttribute('aria-invalid','false');$('pickerSwatch').style.background=colorLayer(layer)[key]}
function changeEditorColor(hex){if(!colorEditor.recorded){checkpoint();colorEditor.recorded=true}const {layer,key}=colorEditor;colorLayer(layer)[key]=hex;if(layer==='service'&&key==='color')layers.service.recolor=true;draw();properties();paintColorPicker()}
function squareColor(e){if(!colorEditor)return;const r=$('colorSquare').getBoundingClientRect();colorEditor.s=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width));colorEditor.v=1-Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));changeEditorColor(hsvToHex(colorEditor.h,colorEditor.s,colorEditor.v))}
$('colorSquare').onpointerdown=e=>{e.preventDefault();$('colorSquare').setPointerCapture(e.pointerId);squareColor(e)};
$('colorSquare').onpointermove=e=>{if(e.buttons===1)squareColor(e)};
$('colorSquare').onkeydown=e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();const delta=(e.key==='ArrowRight'||e.key==='ArrowUp'?1:-1)*.01;if(e.shiftKey||e.key==='ArrowUp'||e.key==='ArrowDown')colorEditor.v=Math.max(0,Math.min(1,colorEditor.v+delta));else colorEditor.s=Math.max(0,Math.min(1,colorEditor.s+delta));changeEditorColor(hsvToHex(colorEditor.h,colorEditor.s,colorEditor.v))};
$('colorHue').oninput=e=>{colorEditor.h=Number(e.target.value);changeEditorColor(hsvToHex(colorEditor.h,colorEditor.s,colorEditor.v))};
$('pickerHex').oninput=e=>{const hex=normalizeHex(e.target.value);e.target.setAttribute('aria-invalid',String(!hex));if(!hex)return;Object.assign(colorEditor,hexToHSV(hex));changeEditorColor(hex)};
$('closeColorPicker').onclick=()=>$('colorPicker').close();
$('pickerEyedropper').onclick=()=>{if(!(colorEditor.layer.startsWith('season:')?seasons.find(s=>s.number===Number(colorEditor.layer.split(':')[1]))?.poster.img:layers.poster.img)){status('Upload or select a poster first.');return}pickingColor={layer:colorEditor.layer,key:colorEditor.key};$('colorPicker').close();canvas.classList.add('color-picking');$('seasonGrid').classList.add('color-picking');canvas.focus();status('Click a color on the poster. Press Escape to cancel.')};

function posterRect(l=layers.poster){if(!l.img)return null;const scale=Math.max(W/l.img.naturalWidth,H/l.img.naturalHeight)*l.scale/100,w=l.img.naturalWidth*scale,h=l.img.naturalHeight*scale;return {x:W*l.x/100-w/2,y:H*l.y/100-h/2,w,h}}
// Editable projects embed each original layer, including custom logos.
function imageForProject(img){if(!img)return null;const surface=document.createElement('canvas');surface.width=img.naturalWidth;surface.height=img.naturalHeight;surface.getContext('2d').drawImage(img,0,0);return surface.toDataURL('image/png')}
function serializeLayer(l){const {img,...config}=l;return {...config,src:'',artwork:imageForProject(img),knockoutWhite:!!img?.knockoutWhite}}
function makeProject(){return {format:'posterr-project',version:1,name:$('workspaceName').textContent,mode,media,selectedLayer,neutralOnly:$('neutralOnly').checked,includeUnknown:$('includeUnknownLanguage').checked,externalIds:{...externalIds},gallery:{posters:saveGallery(images.posters),logos:saveGallery(images.logos)},layers:Object.fromEntries(Object.entries(layers).map(([id,l])=>[id,serializeLayer(l)])),seasonState:{enabled:seasonMode,activeSection,selectedSeason,title:{...seasonTitle},definitions:seasonDefinitions,seasons:seasons.map(s=>({number:s.number,name:s.name,poster:serializeLayer(s.poster),gradient:{...s.gradient},artwork:saveGallery(s.artwork)}))}}}
async function decodeProjectLayer(saved,id,defaults){
 if(!saved||typeof saved.visible!=='boolean')throw new Error('Missing or invalid '+id+' layer.');const l={...defaults};if(Object.hasOwn(defaults,'img'))Object.assign(l,{img:null,src:''});
 for(const key of Object.keys(defaults)){if(['img','src'].includes(key))continue;const value=saved[key];if(typeof value!==typeof defaults[key])throw new Error('Invalid '+id+' '+key);if(typeof value==='number'&&(!Number.isFinite(value)||Math.abs(value)>1000))throw new Error('Invalid layer dimensions.');if(['color','shadowColor'].includes(key)&&!normalizeHex(value))throw new Error('Invalid layer color.');if(typeof value==='string'&&value.length>300)throw new Error('Invalid layer value.');l[key]=['color','shadowColor'].includes(key)?normalizeHex(value):value}
 if((id==='poster'&&(l.scale<10||l.scale>300))||(['title','service'].includes(id)&&(l.width<1||l.width>100)))throw new Error('Invalid artwork size.');
 if(Object.hasOwn(defaults,'img')&&saved.artwork!==null){if(typeof saved.artwork!=='string'||!/^data:image\/png;base64,/.test(saved.artwork)||saved.artwork.length>50e6)throw new Error('Invalid embedded artwork.');l.img=await loadImage(saved.artwork);l.img.knockoutWhite=!!saved.knockoutWhite;l.src=saved.artwork}return l;
}
function validSeasonArtwork(list){if(!Array.isArray(list)||list.length>5000)throw new Error('Invalid season artwork list.');return list.filter(a=>a?.source!=='openposterdb').map(a=>AssetSources.safeAsset(a))}
async function decodeSeasonState(state,projectMode){if(!state)return undefined;if(!Array.isArray(state.seasons)||state.seasons.length>250||projectMode!=='tv'&&(state.enabled||state.seasons.length))throw new Error('Invalid season project.');const title=state.title;if(!title||typeof title.visible!=='boolean'||!['x','y','width'].every(k=>Number.isFinite(title[k])&&title[k]>=0&&title[k]<=100)||title.width<1)throw new Error('Invalid season title position.');const seen=new Set(),next=[];for(const s of state.seasons){if(!Number.isInteger(s.number)||s.number<0||s.number>10000||seen.has(s.number)||typeof s.name!=='string'||s.name.length>300)throw new Error('Invalid season entry.');seen.add(s.number);const poster=await decodeProjectLayer(s.poster,'poster',layers.poster),gradient=await decodeProjectLayer(s.gradient,'gradient',layers.gradient);next.push({number:s.number,name:s.name,poster,gradient,artwork:validSeasonArtwork(s.artwork||[]),error:''})}const definitions=Array.isArray(state.definitions)?state.definitions.filter(s=>Number.isInteger(s.season_number)&&s.season_number>=0&&s.season_number<=10000).map(s=>({season_number:s.season_number,name:String(s.name||'Season '+s.season_number).slice(0,300),poster_path:typeof s.poster_path==='string'&&/^\/[a-zA-Z0-9_.-]+$/.test(s.poster_path)?s.poster_path:null})):[];return {enabled:!!state.enabled,activeSection:state.activeSection==='seasons'?'seasons':'tv',selectedSeason:seen.has(state.selectedSeason)?state.selectedSeason:next[0]?.number??0,title:{x:title.x,y:title.y,width:title.width,visible:title.visible},seasons:next,definitions,loaded:next.length>0}}
async function importProject(data){
 if(data?.format!=='posterr-project'||data.version!==1||!['tv','movie'].includes(data.mode)||typeof data.name!=='string'||data.name.length>300||!data.layers)throw new Error('Choose a valid Posterr project file.');const version=selectionVersion,next={};for(const [id,defaults] of Object.entries(layers))next[id]=await decodeProjectLayer(data.layers[id],id,defaults);const seasonState=await decodeSeasonState(data.seasonState,data.mode),gallery=data.gallery?{posters:validSeasonArtwork(data.gallery.posters),logos:validSeasonArtwork(data.gallery.logos)}:{posters:[],logos:[]};if(version!==selectionVersion){status('Import cancelled because the selected title changed.');return}
 checkpoint();cancelColorPick();restore({layers:next,mode:data.mode,media:data.media&&typeof data.media==='object'?data.media:null,images:gallery,selectedLayer:Object.hasOwn(layers,data.selectedLayer)?data.selectedLayer:'poster',titleLanguage:'all',name:data.name,search:data.name,seasonState,sourceState:{externalIds:safeExternalIds(data.externalIds),extraSeasonArtwork:[],sourceReports:[],artworkSource:'all',seasonSource:'all'}});$('includeUnknownLanguage').checked=data.includeUnknown!==false;$('neutralOnly').checked=data.neutralOnly!==false;status('Poster imported. All layers and seasons are ready to edit.');
}
$('savePosterBtn').onclick=()=>{try{download(new Blob([JSON.stringify(makeProject())],{type:'application/json'}),($('workspaceName').textContent.replace(/[^a-z0-9_-]+/gi,'-')||'poster')+'.posterr.json');status('Editable poster saved with its artwork and layer settings.')}catch{status('Could not save artwork from this image host. Upload the artwork locally and save again.')}};
$('importPosterBtn').onclick=()=>$('projectFile').click();$('projectFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>500e6)throw new Error('Project files must be smaller than 500 MB.');await importProject(JSON.parse(await file.text()))}catch(err){status('Could not import poster: '+err.message)}finally{e.target.value=''}};


// Season posters have independent artwork/gradients and a shared title layout.
function snapshotSeasons(){return {enabled:seasonMode,activeSection,selectedSeason,title:{...seasonTitle},definitions:seasonDefinitions.map(s=>({...s})),loaded:seasonLoaded,seasons:seasons.map(s=>({...s,poster:{...s.poster},gradient:{...s.gradient},artwork:[...s.artwork]}))}}
function restoreSeasons(state){seasonVersion++;seasonLoading=false;seasonMode=!!state?.enabled;activeSection=state?.activeSection==='seasons'?'seasons':'tv';selectedSeason=state?.selectedSeason??0;seasonTitle={...(state?.title||{x:50,y:84,width:78,visible:true})};seasonDefinitions=(state?.definitions||[]).map(s=>({...s}));seasons=(state?.seasons||[]).map(s=>({...s,poster:{...s.poster},gradient:{...s.gradient},artwork:[...(s.artwork||[])]}));seasonLoaded=!!state?.loaded;renderSeasonGrid()}
function clearSeasons(){seasonVersion++;seasonLoading=false;seasonLoaded=false;activeSection='tv';selectedSeason=0;seasons=[];seasonDefinitions=[];renderSeasonGrid()}
function currentSeason(){return seasons.find(s=>s.number===selectedSeason)||seasons[0]}
function seasonComposition(season){return {poster:season.poster,gradient:season.gradient,title:{...seasonTitle,img:layers.title.img},service:{visible:false,img:null}}}
function updateSeasonWorkspace(){const enabled=seasonMode&&mode==='tv';$('seasonMode').checked=enabled;$('seasonMode').disabled=mode!=='tv';$('workspaceSplit').classList.toggle('with-seasons',enabled);$('seasonWorkspace').hidden=!enabled;$('syncFromTV').hidden=!enabled;if(!enabled)activeSection='tv';$('tvTools').hidden=activeSection==='seasons';$('seasonTools').hidden=activeSection!=='seasons';$('tvWorkspace').classList.toggle('workspace-active',enabled&&activeSection==='tv');$('seasonWorkspace').classList.toggle('workspace-active',activeSection==='seasons');$('exportBtn').disabled=activeSection==='seasons'?!currentSeason()?.poster.img:!layers.poster.img}
function activateSection(section,number){if(!seasonMode||mode!=='tv')return;cancelColorPick();editTarget=null;activeSection=section;if(number!==undefined)selectedSeason=number;updateSeasonWorkspace();renderSeasonSelection();properties()}
function renderSeasonSelection(){for(const card of $('seasonGrid').querySelectorAll('[data-season]')){const selected=activeSection==='seasons'&&Number(card.dataset.season)===selectedSeason;card.classList.toggle('selected',selected);card.setAttribute('aria-pressed',String(selected))}}
function fitSeasonGrid(){const grid=$('seasonGrid'),width=grid.clientWidth||600,height=grid.clientHeight||600,count=Math.max(1,seasons.length),columns=Math.min(count,Math.max(1,Math.ceil(Math.sqrt(count*width/(height*0.7)))));grid.style.setProperty('--season-columns',columns);grid.style.setProperty('--season-rows',Math.ceil(count/columns))}
function renderSeasonGrid(){fitSeasonGrid();const message=seasonLoading?'Loading season posters…':!media?'Search for a TV show to load its season posters.':!seasonLoaded?'Enable season mode to load TMDB season posters.':'No seasons are available for this show.';$('seasonCount').textContent=seasons.length+' season'+(seasons.length===1?'':'s');$('seasonGrid').innerHTML=seasons.length?seasons.map(s=>`<button class="season-card" data-season="${s.number}" aria-pressed="false" aria-label="Edit ${esc(s.name)}"><span class="season-card-label">${esc(s.name)}</span><canvas id="season-canvas-${s.number}" width="1000" height="1500" aria-label="${esc(s.name)} poster preview"></canvas><span class="season-card-note">${s.poster.img?'Click to edit':s.error?esc(s.error):seasonLoading?'Loading artwork…':'No TMDB poster · upload artwork'}</span></button>`).join(''):`<p class="season-empty">${message}</p>`;renderSeasonSelection();drawSeasons()}
function drawSeasons(){if(!seasonMode||mode!=='tv')return;for(const season of seasons){const surface=$('season-canvas-'+season.number);if(surface)draw(surface.getContext('2d'),seasonComposition(season))}}
async function loadSeasons(){if(seasonLoading||seasonLoaded||mode!=='tv'||!media?.id)return;const version=++seasonVersion,showId=media.id;seasonLoading=true;renderSeasonGrid();try{
 if(!seasonDefinitions.length){const detail=await api('tv/'+showId);if(version!==seasonVersion)return;seasonDefinitions=(detail.seasons||[]).filter(s=>Number.isInteger(s.season_number)&&s.season_number>=0)}
 if(version!==seasonVersion)return;seasonTitle={x:layers.title.x,y:layers.title.y,width:layers.title.width,visible:layers.title.visible};seasons=seasonDefinitions.map(s=>({number:s.season_number,name:s.name||'Season '+s.season_number,poster:{visible:true,img:null,src:'',x:50,y:50,scale:100},gradient:{...layers.gradient},artwork:[],error:''}));selectedSeason=seasons[0]?.number??0;renderSeasonGrid();
 let next=0;await Promise.all(Array.from({length:Math.min(4,seasons.length)},async()=>{while(next<seasons.length&&version===seasonVersion){const i=next++,season=seasons[i],definition=seasonDefinitions[i],request=(season.request||0)+1;season.request=request;try{let posters=[];try{const result=await api(`tv/${showId}/season/${season.number}/images`);posters=result.posters||[]}catch{season.error='Poster alternatives unavailable'}if(version!==seasonVersion)return;season.artwork=AssetSources.merge(posters,extraSeasonArtwork.filter(a=>a.season===season.number));if(season.request!==request)continue;const preferred=definition.poster_path||posters.find(p=>p.iso_639_1===null)?.file_path||posters[0]?.file_path;if(preferred){const src=imageURL(preferred),img=await loadImage(src);if(version!==seasonVersion)return;if(season.request!==request)continue;Object.assign(season.poster,{img,src});season.error=''}else season.error='No TMDB poster';renderSeasonGrid();if(activeSection==='seasons')renderSeasonTools()}catch{if(version!==seasonVersion)return;season.error='Artwork unavailable · upload a poster';renderSeasonGrid()}}}));
 if(version!==seasonVersion)return;seasonLoaded=true;await mergeSeasonSources();
 }catch(err){if(version===seasonVersion)status('Could not load seasons: '+err.message)}finally{if(version===seasonVersion){seasonLoading=false;renderSeasonGrid();updateSeasonWorkspace();if(activeSection==='seasons')renderSeasonTools()}}}
function seasonSlider(key,label,value,min=0,max=100){return `<div class="prop-row"><label for="season-${key}">${label}</label><output id="season-out-${key}">${Number(value).toFixed(1)}%</output></div><input id="season-${key}" data-season-prop="${key}" type="range" step="0.1" min="${min}" max="${max}" value="${value}">`}
function renderSeasonTools(){const s=currentSeason();let html='<div class="section-title">Season tools</div><div class="source-status">'+sourceSummaryHTML()+'</div><button id="syncFromSeasons" class="wide sync-title">Sync TV show title position to seasons</button>';if(!s){$('seasonTools').innerHTML=html+'<p class="muted">'+(seasonLoading?'Loading seasons…':'Choose a TV show with seasons first.')+'</p>';return}
 html+=`<label class="label" for="seasonSelect">EDIT SEASON</label><select id="seasonSelect">${seasons.map(item=>`<option value="${item.number}" ${item.number===s.number?'selected':''}>${esc(item.name)}</option>`).join('')}</select><div class="divider"></div><div class="section-title">Title logo · all seasons</div><p class="muted">Uses the TV show title artwork. Position and size are shared across every season, independently of the TV show poster.</p><label class="check"><input id="seasonTitleVisible" type="checkbox" role="switch" ${seasonTitle.visible?'checked':''}> Show title on seasons</label>`;
 html+=seasonSlider('titleWidth','Title size',seasonTitle.width,1,100)+seasonSlider('titleX','Horizontal position',seasonTitle.x)+seasonSlider('titleY','Vertical position',seasonTitle.y)+'<button id="centerSeasonTitle" class="wide">Center season titles horizontally</button><div class="divider"></div><div class="section-title">'+esc(s.name)+' · artwork</div>';
 html+=`<label class="check"><input id="seasonPosterVisible" type="checkbox" role="switch" ${s.poster.visible?'checked':''}> Show poster artwork</label>`+seasonSlider('scale','Artwork size',s.poster.scale,10,300)+seasonSlider('x','Horizontal position',s.poster.x,-100,200)+seasonSlider('y','Vertical position',s.poster.y,-100,200)+'<button id="fitSeasonPoster" class="wide">Fit artwork to canvas</button><button id="uploadSeasonPoster" class="wide">↑ Upload season poster</button>';
 html+=`<label class="label" for="seasonArtworkSource">ARTWORK SOURCE</label><select id="seasonArtworkSource"><option value="all">All sources</option><option value="tmdb">TMDB</option><option value="fanart">Fanart.tv</option><option value="tvmaze">TVmaze</option></select><button id="refreshSeasonSources" class="wide">Refresh artwork sources</button><div class="artwork season-artwork">${s.artwork.map((a,i)=>({a,i})).filter(({a})=>seasonSource==='all'||(a.source||'tmdb')===seasonSource).map(({a,i})=>`<button data-season-art="${i}" title="${esc(assetLabel(a))}" class="${s.poster.src===assetURL(a)?'selected':''}"><img crossorigin="anonymous" src="${esc(assetURL(a,'w185'))}" alt="${esc(s.name)} poster option ${i+1}" loading="lazy"><span class="asset-source">${AssetSources.names[a.source||'tmdb']}</span></button>`).join('')}</div><div class="divider"></div><div class="section-title">${esc(s.name)} · gradient</div><label class="check"><input id="seasonGradientVisible" type="checkbox" role="switch" ${s.gradient.visible?'checked':''}> Show gradient</label><div class="color-control"><label for="seasonHex">Gradient color</label><div class="color-fields"><button id="seasonColor" class="color-swatch" style="background:${s.gradient.color}" aria-label="Season gradient color picker"></button><input id="seasonHex" type="text" value="${s.gradient.color}" maxlength="7" spellcheck="false" aria-label="Season gradient hex code"></div></div>`;
 html+=seasonSlider('height','Height',s.gradient.height,1,100)+seasonSlider('spread','Fade spread',s.gradient.spread,1,100)+seasonSlider('opacity','Opacity',s.gradient.opacity)+'<div class="divider"></div><button id="exportSeason" class="wide" '+(!s.poster.img?'disabled':'')+'>↓ Export this season</button><button id="exportSeasons" class="wide" '+(!seasons.some(s=>s.poster.img)?'disabled':'')+'>↓ Export all seasons (.zip)</button>';$('seasonTools').innerHTML=html;$('seasonArtworkSource').value=seasonSource;
}
function syncTitlePosition(from){if(!seasons.length){status('Load season posters first.');return}checkpoint();const source=from==='tv'?layers.title:seasonTitle,target=from==='tv'?seasonTitle:layers.title;Object.assign(target,{x:source.x,y:source.y});draw();properties();status('TV show and season title positions synced.')}
$('seasonMode').onchange=async e=>{checkpoint();seasonMode=e.target.checked&&mode==='tv';if(!seasonMode)activeSection='tv';updateSeasonWorkspace();renderSeasonGrid();properties();if(seasonMode)await loadSeasons()};
$('tvWorkspace').onclick=()=>{if(!pickingColor)activateSection('tv')};$('seasonWorkspace').onclick=e=>{if(pickingColor){if(e.target.tagName==='CANVAS')samplePosterColor(e,e.target);return}const card=e.target.closest('[data-season]');activateSection('seasons',card?Number(card.dataset.season):currentSeason()?.number)};
$('syncFromTV').onclick=()=>syncTitlePosition('tv');
$('seasonTools').oninput=e=>{const s=currentSeason();if(!s)return;if(e.target.id==='seasonHex'){const hex=normalizeHex(e.target.value);e.target.setAttribute('aria-invalid',String(!hex));if(!hex)return;if(editTarget!==e.target){checkpoint();editTarget=e.target}s.gradient.color=hex;$('seasonColor').style.background=hex;drawSeasons();return}const key=e.target.dataset.seasonProp;if(!key)return;if(editTarget!==e.target){checkpoint();editTarget=e.target}const titleKey={titleX:'x',titleY:'y',titleWidth:'width'}[key],target=titleKey?seasonTitle:['height','spread','opacity'].includes(key)?s.gradient:s.poster;target[titleKey||key]=Number(e.target.value);$('season-out-'+key).textContent=Number(e.target.value).toFixed(1)+'%';drawSeasons()};
$('seasonTools').onchange=e=>{editTarget=null;const s=currentSeason();if(e.target.id==='seasonArtworkSource'){seasonSource=e.target.value;renderSeasonTools();return}if(e.target.id==='seasonSelect'){activateSection('seasons',Number(e.target.value));return}if(e.target.id==='seasonHex'&&s)e.target.value=s.gradient.color;const target=e.target.id==='seasonTitleVisible'?seasonTitle:e.target.id==='seasonPosterVisible'?s?.poster:e.target.id==='seasonGradientVisible'?s?.gradient:null;if(target){checkpoint();target.visible=e.target.checked;drawSeasons()}};
$('seasonTools').onclick=e=>{const s=currentSeason();if(e.target.id==='syncFromSeasons'){syncTitlePosition('seasons');return}if(!s)return;if(e.target.id==='refreshSeasonSources')void loadExternalArtwork();if(e.target.id==='seasonColor')openColorPicker('season:'+s.number,'color');if(e.target.id==='centerSeasonTitle'){checkpoint();seasonTitle.x=50;drawSeasons();renderSeasonTools()}if(e.target.id==='fitSeasonPoster'){checkpoint();Object.assign(s.poster,{x:50,y:50,scale:100});drawSeasons();renderSeasonTools()}if(e.target.id==='uploadSeasonPoster'){$('seasonPosterFile').dataset.season=s.number;$('seasonPosterFile').click()}const option=e.target.closest('[data-season-art]');if(option)setSeasonArtwork(s.number,assetURL(s.artwork[Number(option.dataset.seasonArt)]));if(e.target.id==='exportSeason')exportSeason(s);if(e.target.id==='exportSeasons')exportAllSeasons()};
async function setSeasonArtwork(number,src){const s=seasons.find(s=>s.number===number);if(!s)return;const version=seasonVersion,before=snapshot(),request=(s.request||0)+1;s.request=request;try{const img=await loadImage(src);if(version!==seasonVersion||s.request!==request)return;checkpoint(before);Object.assign(s.poster,{img,src,visible:true});s.error='';renderSeasonGrid();renderSeasonTools();updateSeasonWorkspace();status(s.name+' artwork updated.')}catch(err){if(version===seasonVersion)status(err.message)}}
$('seasonPosterFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{await setSeasonArtwork(Number(e.target.dataset.season),await dataURL(file))}catch(err){status(err.message)}finally{e.target.value=''}};
function seasonPNG(s){return new Promise((resolve,reject)=>{const surface=document.createElement('canvas');surface.width=W;surface.height=H;draw(surface.getContext('2d'),seasonComposition(s));try{surface.toBlob(blob=>blob?resolve(blob):reject(new Error('Could not export '+s.name)),'image/png')}catch{reject(new Error('Upload season artwork locally to export it.'))}})}
function seasonFilename(s){return ($('workspaceName').textContent.replace(/[^a-z0-9_-]+/gi,'-')||'poster')+'-season-'+String(s.number).padStart(2,'0')+'.png'}
async function exportSeason(s){if(!s?.poster.img)return;try{download(await seasonPNG(s),seasonFilename(s));status(s.name+' exported at 1000 × 1500.')}catch(err){status(err.message)}}
// Small, uncompressed ZIP writer keeps this static app dependency-free.
function zipFiles(files){const chunks=[],directory=[];let offset=0;const encode=value=>new TextEncoder().encode(value),header=(size)=>{const bytes=new Uint8Array(size);return {bytes,view:new DataView(bytes.buffer)}};for(const file of files){const name=encode(file.name),data=file.data;let crc=0xffffffff;for(const byte of data){crc^=byte;for(let bit=0;bit<8;bit++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}crc=(crc^0xffffffff)>>>0;const local=header(30);local.view.setUint32(0,0x04034b50,true);local.view.setUint16(4,20,true);local.view.setUint16(6,0x800,true);local.view.setUint32(14,crc,true);local.view.setUint32(18,data.length,true);local.view.setUint32(22,data.length,true);local.view.setUint16(26,name.length,true);chunks.push(local.bytes,name,data);const entry=header(46);entry.view.setUint32(0,0x02014b50,true);entry.view.setUint16(4,20,true);entry.view.setUint16(6,20,true);entry.view.setUint16(8,0x800,true);entry.view.setUint32(16,crc,true);entry.view.setUint32(20,data.length,true);entry.view.setUint32(24,data.length,true);entry.view.setUint16(28,name.length,true);entry.view.setUint32(42,offset,true);directory.push(entry.bytes,name);offset+=30+name.length+data.length}const size=directory.reduce((sum,b)=>sum+b.length,0),end=header(22);end.view.setUint32(0,0x06054b50,true);end.view.setUint16(8,files.length,true);end.view.setUint16(10,files.length,true);end.view.setUint32(12,size,true);end.view.setUint32(16,offset,true);return new Blob([...chunks,...directory,end.bytes],{type:'application/zip'})}
async function exportAllSeasons(){const available=seasons.filter(s=>s.poster.img);if(!available.length)return;try{const files=[];for(const s of available){const blob=await seasonPNG(s);files.push({name:seasonFilename(s),data:new Uint8Array(await blob.arrayBuffer())})}download(zipFiles(files),($('workspaceName').textContent.replace(/[^a-z0-9_-]+/gi,'-')||'poster')+'-seasons.zip');status(files.length+' season posters exported'+(available.length<seasons.length?'; seasons without artwork were skipped.':'.'))}catch(err){status(err.message)}}

if(typeof ResizeObserver!=='undefined')new ResizeObserver(fitSeasonGrid).observe($('seasonGrid'));
function readSourceConfig(){try{const saved=JSON.parse(sessionStorage.getItem('posterr-sources')||localStorage.getItem('posterr-sources')||'{}'),config={...AssetSources.defaults};config.tvmaze=saved.tvmaze!==false;for(const key of ['fanartProject','fanartPersonal'])if(typeof saved[key]==='string')config[key]=saved[key];return config}catch{return {...AssetSources.defaults}}}
function assetURL(asset,size='original'){return AssetSources.artworkURL(asset,size,sourceConfig)}
function assetLabel(asset){return AssetSources.names[asset.source||'tmdb']+(asset.type==='background'?' · Background':'')+' · '+(asset.iso_639_1===null?'Language-neutral':asset.iso_639_1==='und'?'Unknown language':asset.iso_639_1||'Unknown language')+(asset.width&&asset.height?` · ${asset.width} × ${asset.height}`:'')}
function safeExternalIds(ids){return {imdb_id:typeof ids?.imdb_id==='string'&&/^tt\d+$/.test(ids.imdb_id)?ids.imdb_id:null,tvdb_id:Number.isInteger(ids?.tvdb_id)&&ids.tvdb_id>0?ids.tvdb_id:null}}
function snapshotSources(){return {externalIds:{...externalIds},extraSeasonArtwork:[...extraSeasonArtwork],sourceReports:sourceReports.map(s=>({...s})),artworkSource,seasonSource}}
function clearSources(){sourceVersion++;sourceController?.abort();sourceController=null;sourceLoading=false;externalIds={};extraSeasonArtwork=[];sourceReports=[];artworkSource='all';seasonSource='all';renderSourceStatus()}
function restoreSources(state){clearSources();externalIds={...(state?.externalIds||{})};extraSeasonArtwork=[...(state?.extraSeasonArtwork||[])];sourceReports=(state?.sourceReports||[]).map(s=>({...s}));artworkSource=state?.artworkSource||'all';seasonSource=state?.seasonSource||'all'}
function sourceSummaryHTML(){if(!sourceConfig.tvmaze&&!sourceConfig.fanartProject&&!sourceConfig.fanartPersonal)return '<p>Connect optional artwork sources in settings.</p>';if(sourceLoading)return '<p>Loading additional artwork sources…</p>';if(sourceReports.length)return sourceReports.map(r=>`<p class="${r.error?'source-error':''}"><strong>${AssetSources.names[r.source]}</strong> · ${esc(r.error||r.note||`${r.posters} posters, ${r.logos} title logos, ${r.seasons} season images`)}</p>`).join('');return '<p>Additional sources: '+[sourceConfig.tvmaze?'TVmaze (TV only)':'',sourceConfig.fanartProject||sourceConfig.fanartPersonal?'Fanart.tv':''].filter(Boolean).join(' · ')+'</p>'}
function renderSourceStatus(){$('sourceStatus').innerHTML=sourceSummaryHTML();$('refreshSources').disabled=sourceLoading||!media}
async function loadExternalArtwork(){if(!media?.id)return;sourceController?.abort();const controller=new AbortController();sourceController=controller;const version=++sourceVersion,selection=selectionVersion,title=media,currentMode=mode,config={...sourceConfig},initialArtworkVersions={...artworkVersions};sourceLoading=true;renderSourceStatus();if(activeSection==='seasons')renderSeasonTools();try{
 let ids={...externalIds};if(currentMode==='tv'&&(config.tvmaze||config.fanartProject||config.fanartPersonal)&&!ids.imdb_id&&!ids.tvdb_id){try{ids=safeExternalIds(await api(`tv/${title.id}/external_ids`))}catch{ids={}}}
 if(version!==sourceVersion||selection!==selectionVersion)return;
 const data=await AssetSources.collect({mediaMode:currentMode,id:title.id,ids,config,signal:controller.signal});if(version!==sourceVersion||selection!==selectionVersion)return;externalIds=ids;extraSeasonArtwork=data.seasons;sourceReports=data.results.map(r=>({source:r.source,note:r.note,error:r.error,posters:r.posters.length,logos:r.logos.length,seasons:r.seasons.length}));
 images={posters:AssetSources.merge(images.posters.filter(a=>!a.source||a.source==='tmdb'),data.posters),logos:AssetSources.merge(images.logos.filter(a=>!a.source||a.source==='tmdb'),data.logos)};
 for(const id of ['poster','title']){let expected=initialArtworkVersions[id];const candidates=id==='poster'?data.posters:data.logos;for(const asset of candidates){if(layers[id].img||artworkVersions[id]!==expected||version!==sourceVersion||selection!==selectionVersion)break;const src=assetURL(asset);if(src){await setArtwork(id,src,false);expected=artworkVersions[id]}}}
 if(version!==sourceVersion||selection!==selectionVersion)return;await mergeSeasonSources();
 }catch{if(version===sourceVersion)sourceReports=[{source:'tvmaze',error:'Additional sources could not be loaded. Try refreshing.'}]}finally{if(version===sourceVersion){sourceLoading=false;renderSourceStatus();properties()}}}
async function mergeSeasonSources(){const version=seasonVersion,source=sourceVersion;for(const s of seasons){s.artwork=AssetSources.merge(s.artwork.filter(a=>!a.source||a.source==='tmdb'),extraSeasonArtwork.filter(a=>a.season===s.number));if(seasonLoaded&&!s.poster.img){const request=s.request;for(const asset of s.artwork){if(s.poster.img||version!==seasonVersion||source!==sourceVersion||s.request!==request)break;try{const src=assetURL(asset);if(!src)continue;const img=await loadImage(src);if(version!==seasonVersion||source!==sourceVersion||s.request!==request)return;Object.assign(s.poster,{img,src});s.error=''}catch{}}}}if(version===seasonVersion&&source===sourceVersion){renderSeasonGrid();updateSeasonWorkspace();if(activeSection==='seasons')renderSeasonTools()}}

function saveGallery(list){return list.flatMap(asset=>{try{return [AssetSources.safeAsset(asset)]}catch{return []}})}
